      SUBROUTINE OSETCC     FLOOR COORDINATE TRANSFORMATION FOR SINGLE ELEMENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8K.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM16C.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'YAW.CIN'CC     LOCAL VARIABLESC      REAL  VDIS1(3)CC----------------------------------------------------------------------      CALL RESET(1)C      IF (TYPEC .EQ. 2) GO TO 200      IF (TYPEC .EQ. 3) GO TO 300      IF (TYPEC .EQ. 4) GO TO 400      IF (TYPEC .EQ. 5) GO TO 500      IF (TYPEC .EQ. 8) GO TO 800      IF (TYPEC .EQ. 11) GO TO 1100      IF (TYPEC .EQ. 13) GO TO 1300      IF (TYPEC .EQ. 16) GO TO 1600      IF (TYPEC .EQ. 18) GO TO 1800      IF (TYPEC .EQ. 19) GO TO 1900      IF (TYPEC .EQ. 20) GO TO 2000      IF (TYPEC .EQ. 25) GO TO 2500      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) GO TO 2800      IF (TYPEC .EQ. 34) GO TO 3400      IF (TYPEC .EQ. 35) GO TO 3500      IF (TYPEC .EQ. 41) GO TO 4100      IF (TYPEC .EQ. 43) GO TO 4300      IF (TYPEC .EQ. 46 .OR. TYPEC .EQ. 47 .OR. TYPEC .EQ. 48) GO TO 300      GO TO 5200CC     2. -- FRINGING FIELDC  200 OFFSET = - 4.0*H0*APB(2)**2*SB**2*LAYK      IF (BEFORE) X0(1,1) = OFFSET      IF (.NOT. BEFORE) X0(1,1) = - OFFSET      GO TO 5200CC     3. -- DRIFT SPACEC  300 X0(1,3)  = L      GO TO 5200CC     4. -- BENDING MAGNETC  400 AL0 = H0*L      CSAL = COS(AL0)      SNAL = SIN(AL0)      O(1,1,1) = CSAL      O(1,3,3) = CSAL      O(1,1,3) = SNAL      O(1,3,1) = - SNAL      IF (H0 .EQ. 0.0) THEN        X0(1,3) = L      ELSE        IF (CSAL .GT. 0.5) X0(1,1) = - SNAL**2/(H0*(1.0 + CSAL))        IF (CSAL .LE. 0.5) X0(1,1) = - (1.0 - CSAL)/H0        X0(1,3) = SNAL/H0      ENDIF      GO TO 5200CC     5. -- QUADRUPOLEC  500 X0(1,3) = L      GO TO 5200CC     8. -- MISALIGNMENTC  800 IF (BEFORE) THEN        DO 810 J = 1, 3        X0(1,J) = VDIS(J)        DO 810 K = 1, 3        O(1,J,K) = RM(J,K)  810   CONTINUE      ELSE        DO 850 J = 1, 3        VD = 0.0        DO 840 K = 1, 3        VD = VD + RM(K,J)*VDIS(K)  840   CONTINUE        VDIS1(J) = - VD  850   CONTINUEC        DO 860 J = 1, 3        X0(1,J) = VDIS1(J)        DO 860 K = 1, 3        O(1,J,K) = RM(J,K)  860   CONTINUE      ENDIFCC     11. -- ACCELERATORC 1100 X0(1,3) = L      GO TO 5200CC     13. -- INPUT-OUTPUT OPTIONSC 1300 IF (CDB .EQ. 11) GO TO 1310      YAW = ATAN(COF(2))      CST = COS(YAW)      SNT = SIN(YAW)      PITCH = ATAN(COF(4)*CST)      CSP = COS(PITCH)      SNP = SIN(PITCH)      X0(1,1) = COF(1)      X0(1,2) = COF(3)      O(1,1,1) = CST      O(1,1,3) = - SNT      O(1,2,1) = - SNT*SNP      O(1,2,2) = CSP      O(1,2,3) = - CST*SNP      O(1,3,1) = SNT*CSP      O(1,3,2) = SNP      O(1,3,3) = CST*CSP      GO TO 5200C 1310 CS = COS(ROLL)      SN = SIN(ROLL)      O(1,1,1) = CS      O(1,1,2) = - SN      O(1,2,1) = SN      O(1,2,2) = CS      GO TO 5200CC     16. -- SPECIAL PARAMETERSC 1600 IF (NPARS .GE. 16 .AND. NPARS .LE. 20) THEN        IF (NPARS .EQ. 19) GO TO 1610        IF (NPARS .EQ. 20) GO TO 1620        J = NPARS - 15        X0(4,J) = PARAM*UFLOOR(1)        IF (J .EQ. 1) XINIT = X0(4,J)        IF (J .EQ. 2) YINIT = X0(4,J)        IF (J .EQ. 3) ZINIT = X0(4,J)      ENDIF      GO TO 5200C 1610 TH = PARAM*UFLOOR(2)      CS = COS(TH)      SN = SIN(TH)      O(1,1,1) = CS      O(1,1,3) = - SN      O(1,3,1) = SN      O(1,3,3) = CS      GO TO 5200C 1620 PH = PARAM*UFLOOR(2)      CS = COS(PH)      SN = SIN(PH)      O(1,2,2) = CS      O(1,2,3) = - SN      O(1,3,2) = SN      O(1,3,3) = CS      GO TO 5200CC     18. -- SEXTUPOLEC 1800 X0(1,3) = L      GO TO 5200CC     19. -- SOLENOIDC 1900 X0(1,3)  =  L      GO TO 5200CC     20. -- COORDINATE ROTATIONC 2000 O(1,1,1) = CSR      O(1,1,2) = SNR      O(1,2,1) = - SNR      O(1,2,2) = CSR      GO TO 5200CC     25. -- OCTUPOLEC 2500 X0(1,3) = L      GO TO 5200CC     28. -- RBEND OR 29. -- SBENDC 2800 IF (TYPEC .EQ. 4) GO TO 2820      IF (TYPEC .EQ. 20) GO TO 2840      GO TO 5200C 2820 AL0 = H0*L      CSAL = COS(AL0)      SNAL = SIN(AL0)      O(1,1,1) = CSAL      O(1,3,3) = CSAL      O(1,1,3) = SNAL      O(1,3,1) = - SNAL      IF (H0 .EQ. 0.0) THEN        X0(1,3) = L      ELSE        IF (CSAL .GT. 0.5) X0(1,1) = - SNAL**2/(H0*(1.0 + CSAL))        IF (CSAL .LE. 0.5) X0(1,1) = - (1.0 - CSAL)/H0        X0(1,3) = SNAL/H0      ENDIF      GO TO 5200C 2840 O(1,1,1) = CSR      O(1,1,2) = SNR      O(1,2,1) = - SNR      O(1,2,2) = CSR      GO TO 5200CC     34. -- PLASMA LENSC 3400 X0(1,3) = L      GO TO 5200CC     35. -- HKICK OR 36. -- VKICKC 3500 X0(1,3) = L      GO TO 5200CC     41. -- ELECTROSTATIC SEPTUMC 4100 X0(1,3) = L      GO TO 5200CC     43. -- REFERENCE COORDINATE SYSTEM SHIFTC 4300 X0(1,1) = - COD(1)      X0(1,2) = - COD(3)      THETA1 = ATAN(CO(2))      CST1 = COS(THETA1)      SNT1 = SIN(THETA1)      PHI1 = ATAN(CO(4)*CST1)      CSP1 = COS(PHI1)      SNP1 = SIN(PHI1)      PHI2 = ATAN(CO(4)-COD(4))      CSP2 = COS(PHI2)      SNP2 = SIN(PHI2)      THETA2 = ATAN((CO(2)-COD(2))*CSP2)      CST2 = COS(THETA2)      SNT2 = SIN(THETA2)      O(1,1,1) = CST2*CST1 + SNT2*SNT1*CSP2*CSP1      O(1,1,2) = SNT2*SNP1      O(1,1,3) = CST2*SNT1 - SNT2*CST1*CSP1      O(1,2,1) = - SNT2*CST1*SNP2 - SNT1*CSP2*SNP1     1         + CST2*SNT1*SNP2*CSP1      O(1,2,2) = CSP2*CSP1 + CST2*SNP2*SNP1      O(1,2,3) = - SNT2*SNT1*SNP2 + CST1*CSP2*SNP1     1         - CST2*CST1*SNP2*CSP1      O(1,3,1) = SNT2*CST1*CSP2 + SNT2*SNP2*SNP1     1         - CST2*SNT1*CSP2*CSP1      O(1,3,2) = SNP2*CSP1 - CST2*CSP2*SNP1      O(1,3,3) = SNT2*SNT1*CSP2 + CST1*SNP2*SNP1     1         + CST2*CST1*CSP2*CSP1      GO TO 5200C 5200 RETURN      END